pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 v1, uint256 v2) internal {
        vm.assume(v1 != v2);
        bool r1;
        try c.SetMinSum(v1) { r1 = false; } catch { r1 = true; }
        vm.assume(!r1);
        bool r2;
        try c.SetMinSum(v2) { r2 = false; } catch { r2 = true; }
        assertTrue(!r2 && c.MinSum() == v2);
    }

    function testFuzz_run(uint256 v1, uint256 v2) public {
        _run(v1, v2);
    }

    receive() external payable {}
}
